const resp = $input.item.json;
let raw = resp.choices ? resp.choices[0].message.content : JSON.stringify(resp);
let extraction = {};
try {
  extraction = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  extraction = {
    disaster_type: 'flood',
    location: $node['Message Normalization'].json.location_hint || 'City Center',
    people_affected: 3,
    resources_required: ['rescue_team'],
    severity: 'critical',
    summary: $node['Message Normalization'].json.message
  };
}
return { ...$node['Message Normalization'].json, extraction: extraction };

const extData = $node['JSON Validation'].json;
const active = $input.item.json.incidents || [];

const newLoc = (extData.extraction.location || '').toLowerCase();
const newType = (extData.extraction.disaster_type || '').toLowerCase();

let match = null;
for (const inc of active) {
  const incLoc = (inc.location || '').toLowerCase();
  const incType = (inc.type || '').toLowerCase();
  if ((incLoc.includes(newLoc) || newLoc.includes(incLoc)) && (incType === newType || incType === 'other')) {
    match = inc;
    break;
  }
}

return {
  ...extData,
  is_duplicate: Boolean(match),
  matched_incident_id: match ? match.incident_id : null,
  matched_incident: match
};

const item = $input.item.json;
const ext = item.extraction;
let score = 20;
const reasons = [];

if (ext.severity === 'critical' || /trapped/i.test(ext.summary)) {
  score += 30;
  reasons.push('Immediate life danger detected');
}
if (/trapped/i.test(ext.summary)) {
  score += 20;
  reasons.push('People reported trapped in distress zone');
}
if (ext.vulnerable_people && ext.vulnerable_people.detected) {
  score += 20;
  reasons.push('Vulnerable population detected');
}
if (ext.people_affected >= 5) {
  score += 15;
  reasons.push('Significant impact scale (5+ people)');
}
if (['flood', 'fire', 'building_collapse'].includes(ext.disaster_type)) {
  score += 15;
  reasons.push('High-risk disaster category: ' + ext.disaster_type);
}

score = Math.min(score, 100);
let level = 'low';
if (score >= 80) level = 'critical';
else if (score >= 60) level = 'high';
else if (score >= 30) level = 'medium';

return {
  ...item,
  priority_score: score,
  priority_level: level,
  priority_reasons: reasons,
  requires_approval: (level === 'critical' || level === 'high')
};

