const active = $input.item.json.incidents || [];
const now = new Date();
const monitored = [];

for (const inc of active) {
  const created = new Date(inc.created_at);
  const minutesElapsed = Math.round((now - created) / 60000);

  monitored.push({
    incident_id: inc.incident_id,
    type: inc.type,
    location: inc.location,
    status: inc.status,
    minutes_elapsed: minutesElapsed,
    requires_escalation: (minutesElapsed > 30 && inc.status === 'responding')
  });
}

return {
  timestamp: now.toISOString(),
  total_monitored: monitored.length,
  monitored_incidents: monitored
};

// ============================================================
// NODE 1 — INPUT VALIDATION
// Validates the decision payload from the Express backend.
// If invalid, throws an error which n8n catches and returns 400.
// ============================================================

const body = $input.first().json.body || $input.first().json;

// Required fields check
if (!body.title || typeof body.title !== 'string' || body.title.trim() === '') {
  throw new Error('Validation failed: Decision title is required.');
}

if (!body.description || typeof body.description !== 'string') {
  throw new Error('Validation failed: Decision description is required.');
}

// Options check
if (!body.options || !Array.isArray(body.options) || body.options.length < 2) {
  throw new Error('Validation failed: At least 2 options are required.');
}

// Criteria check
if (!body.criteria || !Array.isArray(body.criteria) || body.criteria.length < 2) {
  throw new Error('Validation failed: At least 2 criteria are required.');
}

// Weights check
const rawWeights = body.weights || {};
let totalWeight = 0;
for (const crit of body.criteria) {
  const key = crit.key || crit.name;
  const w = parseFloat(rawWeights[key] || 0);
  if (isNaN(w) || w < 0) {
    throw new Error(`Validation failed: Invalid weight for criterion "${crit.name || key}".`);
  }
  totalWeight += w;
}

// Allow some tolerance (e.g. 99.9 to 100.1)
if (totalWeight < 98 || totalWeight > 102) {
  throw new Error(`Validation failed: Criteria weights must sum to 100%. Current sum: ${Math.round(totalWeight)}%.`);
}

// Validate every option has every criterion value
for (const opt of body.options) {
  if (!opt.name || opt.name.trim() === '') {
    throw new Error('Validation failed: Every option must have a name.');
  }
  const optCrit = opt.criteria || {};
  for (const crit of body.criteria) {
    const key = crit.key || crit.name;
    const val = optCrit[key];
    if (val === undefined || val === null || isNaN(parseFloat(val))) {
      throw new Error(`Validation failed: Option "${opt.name}" is missing a numeric value for criterion "${crit.name || key}".`);
    }
    if (parseFloat(val) < 0 || parseFloat(val) > 100) {
      throw new Error(`Validation failed: Score for "${opt.name}" criterion "${crit.name || key}" must be between 0 and 100.`);
    }
  }
}

// Pass cleaned data downstream
return [{ json: body }];

// ============================================================
// NODE 2 — DETERMINISTIC SCORING ENGINE
// CRITICAL: The LLM NEVER invents scores.
// All rankings are computed here mathematically BEFORE Groq.
// ============================================================

const data = $input.first().json;
const options = data.options;
const criteria = data.criteria;
const rawWeights = data.weights || {};

// Step 1: Compute total weight for normalisation
let totalWeight = 0;
for (const crit of criteria) {
  const key = crit.key || crit.name.toLowerCase().replace(/\s+/g, '_');
  totalWeight += parseFloat(rawWeights[key] || rawWeights[crit.key] || 0);
}
if (totalWeight === 0) totalWeight = 100;

// Step 2: Build normalised weight map (decimals 0.0–1.0)
const normWeights = {};
for (const crit of criteria) {
  const key = crit.key || crit.name.toLowerCase().replace(/\s+/g, '_');
  const raw = parseFloat(rawWeights[key] || rawWeights[crit.key] || 0);
  normWeights[key] = raw / totalWeight;
}

// Step 3: Calculate weighted score per option
const scoredOptions = options.map(opt => {
  const optCrit = opt.criteria || {};
  let totalScore = 0;
  const breakdown = {};
  const criteriaDetail = [];

  for (const crit of criteria) {
    const key = crit.key || crit.name.toLowerCase().replace(/\s+/g, '_');
    const rawVal = parseFloat(optCrit[key] !== undefined ? optCrit[key] : optCrit[crit.key] || 0);
    const weight = normWeights[key] || 0;
    const contribution = rawVal * weight;
    breakdown[key] = Math.round(contribution * 100) / 100;
    totalScore += contribution;
    criteriaDetail.push({
      criterion: crit.name || key,
      key: key,
      rawScore: rawVal,
      weight: Math.round(weight * 100),
      contribution: Math.round(contribution * 100) / 100
    });
  }

  return {
    name: opt.name,
    weightedScore: Math.round(totalScore * 10) / 10,
    breakdown,
    criteriaDetail,
    rawCriteria: optCrit
  };
});

// Step 4: Sort descending and assign ranks
scoredOptions.sort((a, b) => b.weightedScore - a.weightedScore);
scoredOptions.forEach((s, idx) => { s.rank = idx + 1; });

const topOption   = scoredOptions[0];
const runnerUp    = scoredOptions[1] || null;
const thirdOption = scoredOptions[2] || null;

// Step 5: Calculate analytical confidence
// Formula: (Completeness×30%) + (Separation×30%) + (Strength×20%) + (Coverage×20%)
const completeness = 1.0; // all values validated in previous node

const separation = runnerUp
  ? Math.min(1.0, Math.max(0.05, (topOption.weightedScore - runnerUp.weightedScore) / 15))
  : 0.5;

const allKeys = criteria.map(c => c.key || c.name);
const topCriteria = topOption.rawCriteria || {};
const strongCount = allKeys.filter(k => {
  const v = parseFloat(topCriteria[k] !== undefined ? topCriteria[k] : 0);
  return v >= 75;
}).length;
const strength = criteria.length > 0 ? strongCount / criteria.length : 0.5;

const coverage = Math.min(1.0, Math.max(0.4, criteria.length / 5));

const rawConf = (completeness * 30) + (separation * 30) + (strength * 20) + (coverage * 20);
const confidence = Math.min(96, Math.max(45, Math.round(rawConf)));
const confidenceLevel = confidence >= 80 ? 'High' : confidence >= 60 ? 'Medium' : 'Low';
const confidenceCategory = confidence >= 80 ? 'High Confidence' : confidence >= 60 ? 'Medium Confidence' : 'Low Confidence';

return [{
  json: {
    ...data,
    scoredOptions,
    topOption,
    runnerUp,
    thirdOption,
    analyticalConfidence: {
      score: confidence,
      level: confidenceLevel,
      category: confidenceCategory,
      breakdown: {
        completeness: Math.round(completeness * 100),
        separation: Math.round(separation * 100),
        strength: Math.round(strength * 100),
        coverage: Math.round(coverage * 100)
      },
      explanation: `Confidence reflects data completeness (${Math.round(completeness*100)}%), score separation between top options (${Math.round(separation*100)}%), top option evidence strength (${Math.round(strength*100)}%), and criteria coverage (${Math.round(coverage*100)}%). It is an analytical indicator, not a guarantee.`
    }
  }
}];

// ============================================================
// NODE 3 — PREPARE GROQ PROMPT
// Builds the full system + user prompt for Groq.
// The deterministic scores are passed as ground truth.
// Groq MUST NOT recalculate or invent scores.
// ============================================================

const item = $input.first().json;

const systemPrompt = `You are an explainable decision-support AI assistant within a Human-in-the-Loop Decision Intelligence Platform.

Your role:
- Help the human UNDERSTAND the decision — not make it for them.
- You are NOT the final decision-maker. The human always retains final authority.
- A deterministic scoring engine has ALREADY calculated the official weighted scores. These are provided to you as ground truth.
- You MUST NOT recalculate, modify, or invent any numerical scores.
- You MUST NOT fabricate data, external facts, or unsupported evidence.
- If data is insufficient to support a claim, explicitly state: "Insufficient data to assess this factor."

Your responsibilities:
1. Identify the highest-ranked option from the deterministic results provided.
2. Write a clear, concise summary of WHY that option ranked first based only on the supplied scores.
3. List the strongest positive factors (criteria where the top option scores well).
4. List negative factors or performance gaps.
5. Identify meaningful trade-offs between the top option and alternatives.
6. Identify realistic risks based ONLY on the data provided.
7. Suggest the most viable alternative options with reasons.
8. DO NOT mention any option that was not in the original input.

Return ONLY valid JSON matching this exact schema — no markdown, no extra text:
{
  "recommendation": {
    "option": "<name of the #1 ranked option exactly as provided>",
    "score": <deterministic score as a number>
  },
  "summary": "<2-3 sentence explanation of why this option ranked first>",
  "reasons": [
    "<reason 1>",
    "<reason 2>",
    "<reason 3>"
  ],
  "evidence": [
    {
      "factor": "<criterion name>",
      "value": <raw score number>,
      "weight": <weight percentage integer>,
      "impact": "positive",
      "explanation": "<one sentence explanation>"
    }
  ],
  "risks": [
    {
      "risk": "<short risk title>",
      "severity": "low|medium|high",
      "explanation": "<one sentence explanation based only on the data>"
    }
  ],
  "alternatives": [
    {
      "option": "<option name exactly as provided>",
      "score": <deterministic score>,
      "reason": "<why this alternative is worth considering>"
    }
  ],
  "tradeoffs": [
    "<tradeoff description 1>",
    "<tradeoff description 2>"
  ]
}`;

const criteriaTable = item.criteria.map(c => {
  const key = c.key || c.name;
  return `  ${c.name} (weight: ${item.weights[key] || item.weights[c.key] || 0}%)`;
}).join('\n');

const scoresTable = item.scoredOptions.map(s => {
  return `  Rank ${s.rank}: ${s.name} — Score: ${s.weightedScore}`;
}).join('\n');

const optionsDetail = item.options.map(opt => {
  const oc = opt.criteria || {};
  const vals = item.criteria.map(c => {
    const key = c.key || c.name;
    return `    ${c.name}: ${oc[key] !== undefined ? oc[key] : oc[c.key] || 'N/A'}`;
  }).join('\n');
  return `  ${opt.name}:\n${vals}`;
}).join('\n');

const userPrompt = `Analyze this decision and provide your advisory output.

Decision: ${item.title}
Description: ${item.description}
Category: ${item.category || 'General'}

Criteria and Weights:
${criteriaTable}

Option Scores (raw values 0-100 per criterion):
${optionsDetail}

DETERMINISTIC CALCULATED RESULTS (source of truth — do not modify):
${scoresTable}

Top option: ${item.topOption.name} with score ${item.topOption.weightedScore}
Runner-up: ${item.runnerUp ? item.runnerUp.name + ' with score ' + item.runnerUp.weightedScore : 'None'}

Provide your JSON advisory analysis now. Remember: the recommendation.option MUST be "${item.topOption.name}" and recommendation.score MUST be ${item.topOption.weightedScore}.`;

return [{
  json: {
    ...item,
    _groqMessages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ]
  }
}];

