// ============================================================
// NODE 4 — PARSE, VALIDATE & GROUND AI RESPONSE
// Enforces that AI never overrides deterministic scores.
// Validates all required fields exist in Groq output.
// ============================================================

const groqResponse = $input.first().json;
const prevData = $('Deterministic Scoring').first().json;

// Extract Groq content
let rawContent = '';
try {
  rawContent = groqResponse.choices[0].message.content;
} catch (e) {
  throw new Error('Groq API returned unexpected response structure: ' + JSON.stringify(groqResponse).substring(0, 200));
}

// Parse JSON
let ai = {};
try {
  ai = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (parseErr) {
  // Attempt partial extraction if JSON is malformed
  console.warn('Groq returned non-parseable JSON, applying fallback structure.');
  ai = {
    summary: 'AI analysis could not be fully parsed. Deterministic scores are authoritative.',
    reasons: [`${prevData.topOption.name} achieved the highest weighted score of ${prevData.topOption.weightedScore}.`],
    evidence: [],
    risks: [],
    alternatives: [],
    tradeoffs: []
  };
}

// ── GROUNDING: Always enforce deterministic top option ──
// AI is never permitted to change the winner.
const topOption = prevData.topOption;
const runnerUp  = prevData.runnerUp;

ai.recommendation = {
  option: topOption.name,
  score: topOption.weightedScore
};

// ── VALIDATE & CLEAN evidence ──
const validOptionNames = prevData.options.map(o => o.name);

if (!Array.isArray(ai.evidence) || ai.evidence.length === 0) {
  // Build evidence from top option's criteria detail
  ai.evidence = topOption.criteriaDetail.map(cd => ({
    factor: cd.criterion,
    value: cd.rawScore,
    weight: cd.weight,
    impact: cd.rawScore >= 80 ? 'positive' : cd.rawScore >= 65 ? 'neutral' : 'negative',
    explanation: `${topOption.name} scored ${cd.rawScore} on ${cd.criterion} (weight ${cd.weight}%, contribution ${cd.contribution}).`
  }));
} else {
  ai.evidence = ai.evidence.map(e => ({
    factor: String(e.factor || 'Factor'),
    value: typeof e.value === 'number' ? e.value : parseFloat(e.value) || 0,
    weight: typeof e.weight === 'number' ? e.weight : parseInt(e.weight) || 0,
    impact: ['positive', 'negative', 'neutral'].includes(e.impact) ? e.impact : 'positive',
    explanation: String(e.explanation || '')
  }));
}

// ── VALIDATE & CLEAN risks ──
if (!Array.isArray(ai.risks) || ai.risks.length === 0) {
  ai.risks = [{
    risk: 'Score Margin',
    severity: 'low',
    explanation: runnerUp
      ? `${runnerUp.name} is ${Math.round((topOption.weightedScore - runnerUp.weightedScore) * 10) / 10} points behind. Reassess if priorities shift.`
      : 'No significant identified risks based on the supplied data.'
  }];
} else {
  ai.risks = ai.risks.map(r => ({
    risk: String(r.risk || 'Operational Risk'),
    severity: ['low', 'medium', 'high'].includes(String(r.severity).toLowerCase()) ? String(r.severity).toLowerCase() : 'medium',
    explanation: String(r.explanation || '')
  }));
}

// ── VALIDATE & CLEAN alternatives ──
// Alternatives must only reference options that were actually submitted.
if (!Array.isArray(ai.alternatives) || ai.alternatives.length === 0) {
  if (runnerUp) {
    ai.alternatives = [{
      option: runnerUp.name,
      score: runnerUp.weightedScore,
      reason: `Runner-up with score ${runnerUp.weightedScore}. Strong candidate if weighting priorities shift.`
    }];
  }
} else {
  ai.alternatives = ai.alternatives
    .filter(a => {
      // Remove alternatives that reference the top option (that's the recommendation, not an alternative)
      const name = String(a.option || '');
      return name !== topOption.name;
    })
    .map(a => {
      // Find matching scored option to get real deterministic score
      const matched = prevData.scoredOptions.find(s => s.name === String(a.option));
      return {
        option: String(a.option),
        score: matched ? matched.weightedScore : (typeof a.score === 'number' ? a.score : 0),
        reason: String(a.reason || 'Viable alternative candidate.')
      };
    });
}

// ── VALIDATE summary, reasons, tradeoffs ──
if (!ai.summary || typeof ai.summary !== 'string' || ai.summary.trim() === '') {
  ai.summary = `${topOption.name} achieves the highest overall weighted score (${topOption.weightedScore}/100) based on the criteria and weights provided.`;
}

if (!Array.isArray(ai.reasons) || ai.reasons.length === 0) {
  ai.reasons = [
    `${topOption.name} ranks #1 with a weighted score of ${topOption.weightedScore}.`,
    runnerUp ? `Leads ${runnerUp.name} by ${Math.round((topOption.weightedScore - runnerUp.weightedScore) * 10) / 10} points.` : 'No close competitor.'
  ];
} else {
  ai.reasons = ai.reasons.map(r => String(r)).filter(r => r.trim() !== '');
}

if (!Array.isArray(ai.tradeoffs)) {
  ai.tradeoffs = [];
}
ai.tradeoffs = ai.tradeoffs.map(t => String(t)).filter(t => t.trim() !== '');

// ── ATTACH confidence (calculated deterministically in previous node) ──
const conf = prevData.analyticalConfidence;
ai.confidence = conf.score;
ai.confidenceCategory = conf.category;
ai.confidenceLevel = conf.level;
ai.confidenceExplanation = conf.explanation;
ai.confidenceBreakdown = conf.breakdown;
ai.source = 'n8n_groq';
ai.analyzedAt = new Date().toISOString();

// ── BUILD FINAL RESPONSE ──
const finalResponse = {
  success: true,
  decisionId: prevData.decisionId || null,
  recommendation: ai.recommendation,
  confidence: {
    score: conf.score,
    level: conf.level,
    category: conf.category,
    explanation: conf.explanation,
    breakdown: conf.breakdown
  },
  calculatedScores: prevData.scoredOptions.map(s => ({
    option: s.name,
    score: s.weightedScore,
    rank: s.rank,
    breakdown: s.breakdown
  })),
  aiAnalysis: {
    recommendation: ai.recommendation,
    confidence: conf.score,
    confidenceCategory: conf.category,
    summary: ai.summary,
    reasons: ai.reasons,
    evidence: ai.evidence,
    risks: ai.risks,
    alternatives: ai.alternatives,
    tradeoffs: ai.tradeoffs,
    source: 'n8n_groq',
    analyzedAt: ai.analyzedAt
  },
  humanDecisionRequired: true
};

return [{ json: finalResponse }];

